function followsPattern(pattern: string, s: string): boolean {
  const words = s.split(" ");
  if (words.length !== pattern.length) return false;
  const toWord = new Map<string, string>();
  const toLetter = new Map<string, string>();
  for (let i = 0; i < words.length; i++) {
    const c = pattern[i], w = words[i];
    if (toWord.has(c) && toWord.get(c) !== w) return false;
    if (toLetter.has(w) && toLetter.get(w) !== c) return false;
    toWord.set(c, w);
    toLetter.set(w, c);
  }
  return true;
}

