class Solution:
    def followsPattern(self, pattern: str, s: str) -> bool:
        words = s.split(" ")
        if len(words) != len(pattern):
            return False
        to_word, to_letter = {}, {}
        for c, w in zip(pattern, words):
            if to_word.setdefault(c, w) != w or to_letter.setdefault(w, c) != c:
                return False
        return True

