function followsPattern(pattern: string, s: string): boolean {
  const words = s.split(" ");
  if (words.length !== pattern.length) return false;
  const shape = (items: string[]) => {
    const first = new Map<string, number>();
    return items.map((x, i) => {
      if (!first.has(x)) first.set(x, i);
      return first.get(x)!;
    });
  };
  const a = shape([...pattern]), b = shape(words);
  return a.every((v, i) => v === b[i]);
}

